CREATE TABLE IF NOT EXISTS project_formations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES assets(id) ON DELETE CASCADE, opportunity_assessment_id uuid REFERENCES opportunity_assessments(id) ON DELETE SET NULL, project_name text NOT NULL, project_type text NOT NULL, formation_stage text NOT NULL DEFAULT 'opportunity', legal_structure text, target_capital numeric(20,2), currency text NOT NULL DEFAULT 'NGN', readiness_score numeric(6,2) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());